type ApiPost = {
  id: number
  title: string
  content: string
  createdAt?: string
}

type PostPayload = {
  title?: unknown
  content?: unknown
}

const posts: ApiPost[] = [
  { id: 1, title: 'First Post', content: 'This is the first post' },
  { id: 2, title: 'Second Post', content: 'This is the second post' },
]

async function readJsonPayload(request: Request): Promise<PostPayload | null> {
  try {
    return (await request.json()) as PostPayload
  } catch {
    return null
  }
}

function getRequiredString(value: unknown): string | null {
  return typeof value === 'string' && value.trim().length > 0
    ? value
    : null
}

export async function GET(): Promise<Response> {
  return Response.json(posts)
}

export async function POST(request: Request): Promise<Response> {
  const payload = await readJsonPayload(request)
  const title = getRequiredString(payload?.title)
  const content = getRequiredString(payload?.content)

  if (!title || !content) {
    return Response.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  const newPost: ApiPost = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  return Response.json(newPost, { status: 201 })
}
type ApiPost = {
  id: number
  title: string
  content: string
  createdAt?: string
  updatedAt?: string
}

type PostPayload = {
  title?: unknown
  content?: unknown
}

type PostRouteContext = {
  params: Promise<{ id: string }>
}

function parsePostId(id: string): number | null {
  const postId = Number.parseInt(id, 10)
  return Number.isNaN(postId) ? null : postId
}

async function readJsonPayload(request: Request): Promise<PostPayload> {
  try {
    return (await request.json()) as PostPayload
  } catch {
    return {}
  }
}

function optionalString(value: unknown): string | undefined {
  return typeof value === 'string' && value.trim().length > 0
    ? value
    : undefined
}

async function getPostId(context: PostRouteContext): Promise<number | null> {
  const { id } = await context.params
  return parsePostId(id)
}

export async function GET(
  _request: Request,
  context: PostRouteContext
): Promise<Response> {
  const id = await getPostId(context)

  if (id === null) {
    return Response.json({ error: 'Invalid post id' }, { status: 400 })
  }

  const post: ApiPost = {
    id,
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return Response.json(post)
}

export async function PUT(
  request: Request,
  context: PostRouteContext
): Promise<Response> {
  const id = await getPostId(context)

  if (id === null) {
    return Response.json({ error: 'Invalid post id' }, { status: 400 })
  }

  const payload = await readJsonPayload(request)
  const updatedPost: ApiPost = {
    id,
    title: optionalString(payload.title) ?? `Post ${id}`,
    content: optionalString(payload.content) ?? `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost)
}

export async function DELETE(
  _request: Request,
  context: PostRouteContext
): Promise<Response> {
  const id = await getPostId(context)

  if (id === null) {
    return Response.json({ error: 'Invalid post id' }, { status: 400 })
  }

  return Response.json({ message: `Post ${id} deleted successfully` })
}
