    title: optionalString(payload.title) ?? `Post ${id}`,
    content: optionalString(payload.content) ?? `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost)
}

export async function DELETE(
  _request: Request,
  context: PostRouteContext
): Promise<Response> {
  const id = await getPostId(context)

  if (id === null) {
    return Response.json({ error: 'Invalid post id' }, { status: 400 })
  }

  return Response.json({ message: `Post ${id} deleted successfully` })
}
